// ===== 格式化与计算工具函数 =====
const CreditMonitorHelper = {
  // 格式化区间值，例如 '[2400000,3400000)' => '240万~340万'
  formatInterval(val) {
    if (!val || val === '0' || val === '0.0' || val === 0) return '0';
    const str = String(val).trim();
    if (str === '0' || str === '') return '0';
    const match = str.match(/[\(\[]\s*([0-9\.]+)\s*,\s*([0-9\.]+)\s*[\)\]]/);
    if (match) {
      const min = parseFloat(match[1]);
      const max = parseFloat(match[2]);
      const minStr = min >= 10000 ? (min / 10000).toFixed(min % 10000 === 0 ? 0 : 1) + '万' : min + '元';
      const maxStr = max >= 10000 ? (max / 10000).toFixed(max % 10000 === 0 ? 0 : 1) + '万' : max + '元';
      return `${minStr} ~ ${maxStr}`;
    }
    const num = parseFloat(str);
    if (!isNaN(num)) {
      if (num === 0) return '0';
      if (num >= 10000) return (num / 10000).toFixed(num % 10000 === 0 ? 0 : 1) + '万';
      return num + '元';
    }
    return str;
  },

  // 格式化数值/金额差值徽标
  formatDiffBadge(val, isAmount = false) {
    if (val === 0 || val === null || val === undefined || val === '') {
      return '<span class="diff-badge diff-zero">持平</span>';
    }
    const num = parseFloat(val);
    if (num > 0) {
      let display = '+' + (isAmount ? (num >= 10000 ? (num / 10000).toFixed(num % 10000 === 0 ? 0 : 1) + '万' : num + '元') : num + '笔');
      return `<span class="diff-badge diff-up"><i class="ri-arrow-up-line"></i>${display}</span>`;
    } else {
      let display = '-' + (isAmount ? (Math.abs(num) >= 10000 ? (Math.abs(num) / 10000).toFixed(Math.abs(num) % 10000 === 0 ? 0 : 1) + '万' : Math.abs(num) + '元') : Math.abs(num) + '笔');
      return `<span class="diff-badge diff-down"><i class="ri-arrow-down-line"></i>${display}</span>`;
    }
  },

  // 获取标签对应的样式颜色
  getTagBadge(tag) {
    const map = {
      '新增机构': { bg: '#e0f2fe', color: '#0369a1', icon: 'ri-bank-line' },
      '信用类新增': { bg: '#dcfce7', color: '#15803d', icon: 'ri-shield-check-line' },
      '保证类新增': { bg: '#fef3c7', color: '#b45309', icon: 'ri-user-star-line' },
      '抵押类新增': { bg: '#f3e8ff', color: '#7e22ce', icon: 'ri-building-line' },
      '质押类新增': { bg: '#fae8ff', color: '#a21caf', icon: 'ri-award-line' },
      '混合类新增': { bg: '#ffedd5', color: '#c2410c', icon: 'ri-node-tree' },
      '信贷扩张': { bg: '#ecfdf5', color: '#047857', icon: 'ri-line-chart-line' },
      '余额下降': { bg: '#f1f5f9', color: '#64748b', icon: 'ri-arrow-down-circle-line' },
      '平稳无变化': { bg: '#f8fafc', color: '#94a3b8', icon: 'ri-subtract-line' }
    };
    const c = map[tag] || { bg: '#f3f4f6', color: '#4b5563', icon: 'ri-price-tag-3-line' };
    return `<span class="tag-pill" style="background:${c.bg};color:${c.color};"><i class="${c.icon}"></i> ${tag}</span>`;
  },

  // 生成单企智能营销与信贷动向洞察报告
  generateInsight(rec) {
    const changes = [];
    if (rec.instCount_diff > 0) {
      changes.push(`在贷机构数由 <strong>${rec.instCount_T0}家</strong> 增至 <strong>${rec.instCount_T1}家</strong>（净增 ${rec.instCount_diff} 家合作资金方，表明已在其他银行/机构成功开户获批）`);
    }
    if (rec.creditCount_diff > 0 || rec.creditBal_diff > 0) {
      changes.push(`纯信用类贷款新增 <strong>${rec.creditCount_diff}笔</strong>，信用余额净增 <strong>${this.formatInterval(rec.creditBal_diff)}</strong>`);
    }
    if (rec.guaranteeCount_diff > 0 || rec.guaranteeBal_diff > 0) {
      changes.push(`保证类贷款新增 <strong>${rec.guaranteeCount_diff}笔</strong>，保证余额净增 <strong>${this.formatInterval(rec.guaranteeBal_diff)}</strong>`);
    }
    if (rec.mortgageCount_diff > 0 || rec.mortgageBal_diff > 0) {
      changes.push(`抵押类贷款新增 <strong>${rec.mortgageCount_diff}笔</strong>，抵押余额净增 <strong>${this.formatInterval(rec.mortgageBal_diff)}</strong>`);
    }
    if (rec.pledgeCount_diff > 0 || rec.pledgeBal_diff > 0) {
      changes.push(`质押类贷款新增 <strong>${rec.pledgeCount_diff}笔</strong>，质押余额净增 <strong>${this.formatInterval(rec.pledgeBal_diff)}</strong>`);
    }
    if (rec.totalBal_diff > 0) {
      changes.push(`在贷贷款总余额下界净增约 <strong>${this.formatInterval(rec.totalBal_diff)}</strong>（目前总余额区间达 <strong>${this.formatInterval(rec.totalBal_T1)}</strong>）`);
    } else if (rec.totalBal_diff < 0) {
      changes.push(`在贷贷款总额净减约 <strong>${this.formatInterval(Math.abs(rec.totalBal_diff))}</strong>，可能存在到期还本结清或额度到期`);
    }

    let advise = '';
    if (rec.isNew) {
      if (rec.instCount_diff > 0) {
        advise = '【竞争分流预警】企业在名单交付后已有新增机构授信介入，反映其近期融资意向极其强烈且资信资质优良。建议合作银行客户经理加急跟进，重点推介更具竞争力的综合费率或提供供应链结算支持，防范优质客户被同业完全锁定。';
      } else {
        advise = '【授信扩张提额】企业近期信贷余额与笔数呈增长趋势，流动资金需求活跃。建议客户经理主动跟进存量授信使用情况，适时开展二期增额授信或推荐匹配的组合担保产品。';
      }
    } else if (rec.totalBal_diff < 0) {
      advise = '【续贷还本机会】企业总负债与在贷笔数出现缩减，可能近期有大额资金回笼或贷款到期。建议客户经理在还款周期节点前夕主动对接续贷、转贷或无还本续贷方案。';
    } else {
      advise = '【平稳维护】企业近期在贷信贷结构保持稳定，可维持常规季度拜访并挖掘企业在日常经营中的税贷、票据与结算需求。';
    }

    return {
      changesSummary: changes.length > 0 ? changes : ['企业各类型在贷信贷笔数及余额区间在对比期内保持稳定无变动。'],
      marketingAdvice: advise
    };
  }
};

// 导出全局变量
if (typeof window !== 'undefined') {
  window.CREDIT_BATCH_LIST = CREDIT_BATCH_LIST;
  window.CREDIT_MONITORING_DATA = CREDIT_MONITORING_DATA;
  window.CreditMonitorHelper = CreditMonitorHelper;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { CREDIT_BATCH_LIST, CREDIT_MONITORING_DATA, CreditMonitorHelper };
}
